#!/usr/bin/env bash
# SPDX-License-Identifier: AGPL-3.0
# Copyright (C) 2024-2026 Breakdown RS Contributors
# Co-authored-by: muse-spark-1.3-contributor-free (opencode)
# Co-authored-by: deepseek-v4.1-flash (opencode-go)
# test-add-spdx-headers.sh - Guard test for add-spdx-headers.sh (issues #345,
# #814).
#
# Runs add-spdx-headers.sh against a fixture tree containing generated files
# and asserts they are left untouched, while hand-authored files still gain a
# header. Also pins the `--check` / `--dry-run` contract (issue #814): the
# verification modes must never write, `--check` must exit 1 and name the
# offenders, and a shell script's `#!` line must stay line 1.
# Self-contained: builds the fixture in a temp dir, cleans up on exit.
#
# Usage: ./test-add-spdx-headers.sh
# Exit status: 0 when all assertions hold, 1 otherwise.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
FIXTURE="$(mktemp -d)"
trap 'rm -rf "$FIXTURE"' EXIT

failures=0
fail() {
    echo "❌ FAIL: $1" >&2
    failures=$((failures + 1))
}
pass() {
    echo "✅ PASS: $1"
}

# --- Fixture: generated files that must be left untouched ---
mkdir -p "$FIXTURE/backend"
mkdir -p "$FIXTURE/frontend-flutter/vendor/breakdown_api/lib/src"
mkdir -p "$FIXTURE/frontend-flutter/lib/src"
mkdir -p "$FIXTURE/frontend-flutter/.dart_tool"
# Trees added to the skip list by issue #814 (regenerated output and frozen
# governance history).
mkdir -p "$FIXTURE/frontend-flutter/lib/l10n/generated"
mkdir -p "$FIXTURE/backend/rules-tests/__snapshots__"
mkdir -p "$FIXTURE/openspec/changes/archive/2026-01-01-frozen-change"

printf 'components:\n  schemas: {}\n' > "$FIXTURE/backend/openapi.yaml"
# gen-l10n output: regenerated by `flutter gen-l10n`, which cannot emit a header.
printf '// ignore_for_file: type=lint\nclass AppLocalizations {}\n' > "$FIXTURE/frontend-flutter/lib/l10n/generated/app_localizations.dart"
# ast-grep snapshot output: rewritten by the snapshot suite.
printf 'id: reqwest-no-dangerous-tls\nsnapshots: []\n' > "$FIXTURE/backend/rules-tests/__snapshots__/reqwest-no-dangerous-tls-snapshot.yml"
# Frozen governance history: retrofitting an archived change rewrites the record.
printf '# Frozen proposal\n\nBody.\n' > "$FIXTURE/openspec/changes/archive/2026-01-01-frozen-change/proposal.md"
# Path-exclusion fixtures intentionally omit any GENERATED banner so each
# path predicate is tested independently of the content-level guard. Only
# future_generated.dart below exercises the content guard.
printf '// Vendor artifact — committed output of scripts/regen-client.sh.\n// other content\n' > "$FIXTURE/frontend-flutter/vendor/breakdown_api/lib/src/soll_ist_report.dart"
printf '// build_runner output\n// other content\n' > "$FIXTURE/frontend-flutter/lib/src/cache_database.g.dart"
printf '// freezed output\n// other content\n' > "$FIXTURE/frontend-flutter/lib/src/model.freezed.dart"
printf '// mockito output\n// other content\n' > "$FIXTURE/frontend-flutter/lib/src/service.mocks.dart"
printf '// GENERATED, DO NOT EDIT: future generated tree at an unknown path.\n// covered by the content-level banner guard, not the path prune.\n' > "$FIXTURE/frontend-flutter/lib/src/future_generated.dart"
printf '// some dart_tool artifact\n' > "$FIXTURE/frontend-flutter/.dart_tool/package_config.dart"

# --- Fixture: hand-authored files that must gain a header ---
mkdir -p "$FIXTURE/backend/src"
mkdir -p "$FIXTURE/frontend-flutter/lib/src"
mkdir -p "$FIXTURE/docs"
printf 'fn main() {}\n' > "$FIXTURE/backend/src/main.rs"
printf 'void main() {}\n' > "$FIXTURE/frontend-flutter/lib/src/hand_written.dart"
# Authored OpenAPI document outside backend/: must NOT match the scoped
# backend/openapi.yaml exclusion, so it still gains a header.
printf 'components:\n  schemas: {}\n' > "$FIXTURE/docs/openapi.yaml"
# A shell script's `#!` line must survive as line 1 (issue #814 retrofit).
mkdir -p "$FIXTURE/backend/scripts"
printf '#!/usr/bin/env bash\necho hi\n' > "$FIXTURE/backend/scripts/tool.sh"
# pi-rules instruction files open with YAML frontmatter; the header must land
# after the closing `---`, not inside it (issue #814 regression guard).
mkdir -p "$FIXTURE/.github/instructions"
printf -- '---\nglobs: ["**/*.dart"]\n---\n\n# Rule\n\nBody.\n' > "$FIXTURE/.github/instructions/rule.md"

# Record pre-run checksums of every generated file.
declare -A before
while IFS= read -r f; do
    before["$f"]="$(sha256sum "$f" | cut -d' ' -f1)"
done < <(find "$FIXTURE/backend/openapi.yaml" \
    "$FIXTURE/frontend-flutter/vendor" \
    "$FIXTURE/frontend-flutter/lib/src/cache_database.g.dart" \
    "$FIXTURE/frontend-flutter/lib/src/model.freezed.dart" \
    "$FIXTURE/frontend-flutter/lib/src/service.mocks.dart" \
    "$FIXTURE/frontend-flutter/lib/src/future_generated.dart" \
    "$FIXTURE/frontend-flutter/lib/l10n/generated" \
    "$FIXTURE/backend/rules-tests/__snapshots__" \
    "$FIXTURE/openspec/changes/archive" \
    "$FIXTURE/frontend-flutter/.dart_tool" -type f)

# --- Act ---
bash "$SCRIPT_DIR/add-spdx-headers.sh" "$FIXTURE" > /dev/null

# --- Assert: generated files byte-identical, no SPDX injected ---
for f in "${!before[@]}"; do
    after="$(sha256sum "$f" | cut -d' ' -f1)"
    if [ "$after" != "${before[$f]}" ]; then
        fail "$f was modified (expected untouched)"
    elif grep -q "SPDX-License-Identifier" "$f"; then
        fail "$f contains an SPDX header (expected none)"
    else
        pass "$f left untouched"
    fi
done

# --- Assert: hand-authored files gained a header ---
for f in "$FIXTURE/backend/src/main.rs" "$FIXTURE/frontend-flutter/lib/src/hand_written.dart" "$FIXTURE/docs/openapi.yaml"; do
    if grep -q "SPDX-License-Identifier" "$f"; then
        pass "$f gained SPDX header"
    else
        fail "$f missing SPDX header (expected it to be added)"
    fi
done

# --- Assert: a shebang survives as line 1 (issue #814) ---
if [ "$(head -n 1 "$FIXTURE/backend/scripts/tool.sh")" = "#!/usr/bin/env bash" ]; then
    pass "backend/scripts/tool.sh keeps its shebang on line 1"
else
    fail "backend/scripts/tool.sh lost its shebang (header must go below it)"
fi
if [ "$(sed -n '2p' "$FIXTURE/backend/scripts/tool.sh")" = "# SPDX-License-Identifier: AGPL-3.0" ]; then
    pass "backend/scripts/tool.sh carries the SPDX header on line 2"
else
    fail "backend/scripts/tool.sh is missing the SPDX header below the shebang"
fi

# --- Assert: Markdown frontmatter stays frontmatter (issue #814) ----------
RULE_FILE="$FIXTURE/.github/instructions/rule.md"
if [ "$(head -n 1 "$RULE_FILE")" = "---" ] && [ "$(sed -n '3p' "$RULE_FILE")" = "---" ]; then
    pass "rule file frontmatter still opens and closes on lines 1 and 3"
else
    fail "rule file frontmatter was displaced by the header"
fi
if [ "$(awk '/SPDX-License-Identifier/ { print NR; exit }' "$RULE_FILE")" = "5" ] && \
   [ -z "$(sed -n '4p' "$RULE_FILE")" ]; then
    pass "rule file header sits below a blank line after the frontmatter"
else
    fail "rule file header is not below the closing frontmatter delimiter"
fi

# --- Assert: --check reports offenders, never writes, exits 1 ---------------
MISSING_FILE="$FIXTURE/docs/still_missing.md"
printf '# Not yet headered\n\nBody.\n' > "$MISSING_FILE"
missing_before="$(sha256sum "$MISSING_FILE" | cut -d' ' -f1)"

check_output="$(bash "$SCRIPT_DIR/add-spdx-headers.sh" --check "$FIXTURE" 2>&1)" && check_status=0 || check_status=$?
if [ "$check_status" -eq 1 ]; then
    pass "--check exits 1 on a tree with an offender"
else
    fail "--check exited $check_status (expected 1)"
fi
case "$check_output" in
    *"still_missing.md"*) pass "--check names the offending file" ;;
    *) fail "--check did not name docs/still_missing.md" ;;
esac
if [ "$(sha256sum "$MISSING_FILE" | cut -d' ' -f1)" = "$missing_before" ]; then
    pass "--check did not write to the offending file"
else
    fail "--check modified the offending file (verification must be read-only)"
fi

# --- Assert: --check is clean once every file carries a header --------------
bash "$SCRIPT_DIR/add-spdx-headers.sh" "$MISSING_FILE" > /dev/null
if bash "$SCRIPT_DIR/add-spdx-headers.sh" --check "$FIXTURE" > /dev/null 2>&1; then
    pass "--check exits 0 on a fully headered tree"
else
    fail "--check exited non-zero on a fully headered tree"
fi

# --- Assert: --dry-run lists but never writes ------------------------------
printf '# Second unheadered doc\n\nBody.\n' > "$MISSING_FILE"
dry_before="$(sha256sum "$MISSING_FILE" | cut -d' ' -f1)"
dry_output="$(bash "$SCRIPT_DIR/add-spdx-headers.sh" --dry-run "$FIXTURE" 2>&1)" && dry_status=0 || dry_status=$?
if [ "$dry_status" -eq 0 ]; then
    pass "--dry-run exits 0 even with a pending change"
else
    fail "--dry-run exited $dry_status (expected 0)"
fi
case "$dry_output" in
    *"Would add header to"*) pass "--dry-run lists the pending change" ;;
    *) fail "--dry-run did not list the pending change" ;;
esac
if [ "$(sha256sum "$MISSING_FILE" | cut -d' ' -f1)" = "$dry_before" ]; then
    pass "--dry-run did not write"
else
    fail "--dry-run modified a file (dry-run must be read-only)"
fi

# --- Assert: an unknown option fails loudly instead of silently applying ---
if bash "$SCRIPT_DIR/add-spdx-headers.sh" --bogus "$FIXTURE" > /dev/null 2>&1; then
    fail "--bogus was accepted (unknown options must exit non-zero)"
else
    pass "--bogus is rejected"
fi

# --- Assert: an unstattable path fails instead of passing vacuously ---------
# The pre-commit hook passes repo-root-relative paths (issue #814): a wrong
# working directory must break the check, not silently verify nothing.
if bash "$SCRIPT_DIR/add-spdx-headers.sh" --check "$FIXTURE/does-not-exist.md" > /dev/null 2>&1; then
    fail "a non-existent path was accepted (expected a non-zero exit)"
else
    pass "a non-existent path is rejected"
fi

if [ "$failures" -gt 0 ]; then
    echo "" >&2
    echo "❌ $failures assertion(s) failed." >&2
    exit 1
fi

echo ""
echo "✅ All add-spdx-headers guard assertions passed."
